/* KGN V17: selectable wholesale sizes and pack multiples. Read-only cloud client. */
(()=>{'use strict';
if(!document.querySelector('link[data-kgn-v17]')){const css=document.createElement('link');css.rel='stylesheet';css.href='./bundle.css?v=17';css.dataset.kgnV17='';document.head.append(css);}
const q=id=>document.getElementById(id), LANG={hi:{size:'उपलब्ध साइज़',pack:'बंडल चुनें',add:'इन्क्वायरी में जोड़ें',select:'साइज़ चुनें',bundle:'बंडल',pieces:'पीस',missing:'पहले साइज़ और बंडल चुनें',legacy:'पुराना MOQ',empty:'इन्क्वायरी खाली है',close:'बंद करें',summary:'साइज़ और बंडल',stock:'स्टॉक/साइज़ की पुष्टि करें',title:'अपना थोक बंडल चुनें'},en:{size:'Available sizes',pack:'Choose bundle',add:'Add to enquiry',select:'Select sizes',bundle:'Bundle',pieces:'pieces',missing:'Choose a size and bundle',legacy:'Legacy minimum',empty:'Enquiry is empty',close:'Close',summary:'Sizes and bundles',stock:'Please confirm stock and size distribution',title:'Choose your wholesale bundle'},ur:{size:'دستیاب سائز',pack:'بنڈل منتخب کریں',add:'انکوائری میں شامل کریں',select:'سائز منتخب کریں',bundle:'بنڈل',pieces:'پیس',missing:'سائز اور بنڈل منتخب کریں',legacy:'پرانا کم از کم',empty:'انکوائری خالی ہے',close:'بند کریں',summary:'سائز اور بنڈل',stock:'اسٹاک اور سائز کی تصدیق کریں',title:'ہول سیل بنڈل منتخب کریں'}};
const label=()=>LANG[document.documentElement.lang]||LANG.hi, esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='kgn_v17_bundle_lines';let lines=[];try{let a=JSON.parse(localStorage.getItem(STORAGE)||'[]');if(Array.isArray(a))lines=a.filter(x=>x&&typeof x.id==='string'&&Number.isInteger(x.pack)&&x.pack>0&&Number.isInteger(x.bundles)&&x.bundles>0&&Array.isArray(x.sizes)).slice(0,100)}catch{}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(lines))}catch{};cart={};for(const x of lines)cart[x.id]=(cart[x.id]||0)+x.bundles;storeSet('kgn_v11_cart',JSON.stringify(cart))}
const dlg=document.createElement('dialog');dlg.className='kgn-bundle-dialog';dlg.id='kgnBundleDialog';dlg.innerHTML='<div class="kgn-dialog-head"><strong id="kgnBundleHeading"></strong><button class="kgn-dialog-close" id="kgnBundleClose" type="button" aria-label="Close">×</button></div><div id="kgnBundleContent" class="kgn-dialog-content"></div>';let selectedProduct=null,selectedPack=null,selectedSizes=[];
const packs=p=>Array.isArray(p.packOptions)&&p.packOptions.length?p.packOptions.filter(n=>[3,4,5,6].includes(n)).sort((a,b)=>a-b):[Math.max(1,Number(p.moq)||1)];
const sizeList=p=>Array.isArray(p.sizeOptions)?p.sizeOptions:[];
function allowedPackOptions(p){return packs(p).filter(n=>!selectedSizes.includes('20-30')||n===6)}
function paintDialog(){const p=selectedProduct;if(!p)return;const t=label(),size=sizeList(p),choices=allowedPackOptions(p);if(!choices.includes(selectedPack))selectedPack=null;q('kgnBundleHeading').textContent=t.title;q('kgnBundleClose').setAttribute('aria-label',t.close);q('kgnBundleContent').innerHTML=`<h3>${esc(displayName(p))}</h3><div class="kgn-option-title">📏 ${t.size}</div><div class="kgn-chip-grid">${size.length?size.map(s=>`<button type="button" class="kgn-chip ${selectedSizes.includes(s)?'selected':''}" data-kgn-size="${esc(s)}" aria-pressed="${selectedSizes.includes(s)}">${esc(s)}</button>`).join(''):`<small>${t.stock}</small>`}</div><div class="kgn-option-title">📦 ${t.pack}</div><div class="kgn-chip-grid">${choices.map(n=>`<button type="button" class="kgn-chip ${selectedPack===n?'selected':''}" data-kgn-pack="${n}" aria-pressed="${selectedPack===n}">${n} ${t.pieces}</button>`).join('')}</div><p class="kgn-help">${t.stock}. 20-30: 6 ${t.pieces} only.</p><button type="button" id="kgnBundleConfirm" class="kgn-dialog-primary">${t.add}</button>`;}
function openPicker(p){selectedProduct=p;selectedSizes=[];selectedPack=null;paintDialog();dlg.showModal()}
function addLine(){const p=selectedProduct,t=label();if(!p||!selectedPack||sizeList(p).length&&!selectedSizes.length){alert(t.missing);return;}if(selectedSizes.includes('20-30')&&selectedPack!==6){alert('20-30: 6 pieces only');return;}const key=[...selectedSizes].sort().join('|'),line=lines.find(x=>x.id===p.id&&x.pack===selectedPack&&[...x.sizes].sort().join('|')===key);if(line)line.bundles=Math.min(999,line.bundles+1);else lines.push({id:p.id,pack:selectedPack,sizes:[...selectedSizes],bundles:1});persist();renderAll();dlg.close();toast(tr('added'))}
function extrasOnCards(){document.querySelectorAll('.product-card').forEach(card=>{if(card.querySelector('.kgn-pack-readout'))return;const title=card.querySelector('.product-body h3'),add=card.querySelector('[data-add]');if(!title||!add)return;const p=products.find(x=>x.id===add.dataset.add);if(!p)return;const div=document.createElement('div');div.className='kgn-pack-readout';div.textContent='📏 '+(sizeList(p).join(', ')||label().stock)+' · 📦 '+packs(p).join(' / ')+' '+label().pieces;add.before(div)})}
function newCart(){const t=label(),valid=lines.filter(x=>products.some(p=>p.id===x.id));if(valid.length!==lines.length){lines=valid;persist()}let bundles=lines.reduce((n,x)=>n+x.bundles,0),pieces=lines.reduce((n,x)=>n+x.pack*x.bundles,0);q('cartCount').hidden=!bundles;q('cartCount').textContent=bundles;q('selectedCount').textContent=pieces+' '+t.pieces;q('enquiryForm').hidden=!bundles;q('cartItems').innerHTML=bundles?lines.map((x,i)=>{let p=products.find(p=>p.id===x.id);if(!p)return '';return `<div class="kgn-cart-line"><img src="${esc(imgSrc(p.image))}" alt=""><div class="kgn-cart-info"><strong>${esc(displayName(p))}</strong><small>📏 ${esc(x.sizes.join(', ')||t.stock)}</small><small>📦 ${x.pack} ${t.pieces} × ${x.bundles} = ${x.pack*x.bundles} ${t.pieces}</small><div class="kgn-qty"><button type="button" data-kgn-qty="${i}" data-d="-1" aria-label="Decrease">−</button><b>${x.bundles}</b><button type="button" data-kgn-qty="${i}" data-d="1" aria-label="Increase">+</button></div></div></div>`}).join(''):`<div class="empty">${t.empty}</div>`;extrasOnCards()}
function newMessage(){const l=document.documentElement.lang,t=label();const result=l==='en'?['Hello K.G.N. Fashion Zone,','Wholesale enquiry:']:l==='ur'?['السلام علیکم K.G.N. Fashion Zone،','ہول سیل انکوائری:']:['नमस्ते K.G.N. Fashion Zone,','थोक कपड़ों की इन्क्वायरी:'];if(q('buyerName').value.trim())result.push(tr('buyer')+': '+q('buyerName').value.trim());if(q('buyerCity').value.trim())result.push(tr('city')+': '+q('buyerCity').value.trim());for(const x of lines){const p=products.find(p=>p.id===x.id);if(!p)continue;const rate=p.saleRate??p.rate;result.push('• '+displayName(p)+(p.sku?' ['+p.sku+']':'')+' | 📏 '+(x.sizes.join(', ')||t.stock)+' | 📦 '+x.pack+' '+t.pieces+' × '+x.bundles+' = '+x.pack*x.bundles+' '+t.pieces+(rate!==null?' | '+money(rate)+'/'+tr('units')[p.unit]:''))}result.push(t.stock+'. '+tr('notOrder'));return result.join('\n')}
async function freshOptions(){if(!cloudConfigured||!sb)return;const {data,error}=await sb.from('products').select('id,size_options,pack_options').eq('published',true).limit(250);if(error){console.warn('KGN V17 bundle columns missing. Run SQL migration first.',error);setStatus('V17 setup: Supabase SQL में bundle migration चलाएँ।','error');return}for(const p of products){const r=(data||[]).find(x=>x.id===p.id);p.sizeOptions=Array.isArray(r?.size_options)?r.size_options:[];p.packOptions=Array.isArray(r?.pack_options)?r.pack_options:[]}if(!lines.length&&cart&&Object.keys(cart).length){lines=products.filter(p=>cart[p.id]>0).map(p=>({id:p.id,pack:packs(p)[0],sizes:[],bundles:Math.max(1,Math.min(999,Number(cart[p.id])||1))}));}persist();renderAll()}
function install(){document.body.append(dlg);q('kgnBundleClose').onclick=()=>dlg.close();dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close();const s=e.target.closest('[data-kgn-size]');if(s){selectedSizes=selectedSizes.includes(s.dataset.kgnSize)?selectedSizes.filter(x=>x!==s.dataset.kgnSize):[...selectedSizes,s.dataset.kgnSize];paintDialog()}const b=e.target.closest('[data-kgn-pack]');if(b){selectedPack=Number(b.dataset.kgnPack);paintDialog()}if(e.target.id==='kgnBundleConfirm')addLine()});
window.renderCart=newCart;window.makeMessage=newMessage;
const oldRefresh=window.refreshCloud;window.refreshCloud=async function(){await oldRefresh();await freshOptions()};
// Capture before legacy click handler: never let a 6-piece item become a single-piece enquiry.
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){e.preventDefault();e.stopImmediatePropagation();const p=products.find(p=>p.id===add.dataset.add);if(p)openPicker(p);return}const qty=e.target.closest('[data-kgn-qty]');if(qty){e.preventDefault();e.stopImmediatePropagation();const x=lines[Number(qty.dataset.kgnQty)];if(!x)return;x.bundles+=Number(qty.dataset.d);if(x.bundles<=0)lines.splice(Number(qty.dataset.kgnQty),1);persist();renderAll();return}},true);
// Import old enquiry items on cloud sync; never interpret one click as one loose piece.
setTimeout(()=>freshOptions(),1100);
const originalRender=window.renderCards;window.renderCards=function(host,arr){originalRender(host,arr);extrasOnCards()};
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
